{
  "recipes": [
    {
      "title": "Thon rôti méditerranéen",
      "type": "plat",
      "servings": 6,
      "ingredients": [
        {
          "raw": "1 tranche de thon de 1 kg",
          "quantity": 1,
          "unit": "tranche",
          "label": "de thon de 1 kg"
        },
        {
          "raw": "4 oignons",
          "quantity": 4,
          "unit": null,
          "label": "oignons"
        },
        {
          "raw": "3 cuillères à soupe d'huile d'olive",
          "quantity": 3,
          "unit": "cuillères à soupe",
          "label": "d'huile d'olive"
        },
        {
          "raw": "3 gousses d'ail",
          "quantity": 3,
          "unit": "gousses",
          "label": "d'ail"
        },
        {
          "raw": "1 bouquet garni",
          "quantity": 1,
          "unit": "bouquet",
          "label": "garni"
        },
        {
          "raw": "100 g d'olives noires dénoyautées",
          "quantity": 100,
          "unit": "g",
          "label": "d'olives noires dénoyautées"
        },
        {
          "raw": "3 citrons confits",
          "quantity": 3,
          "unit": null,
          "label": "citrons confits"
        },
        {
          "raw": "Le jus de 2 citrons",
          "quantity": 2,
          "unit": "jus de",
          "label": "citrons"
        },
        {
          "raw": "Sel et poivre",
          "quantity": null,
          "unit": null,
          "label": "Sel et poivre"
        }
      ],
      "steps": [
        "Saler et poivrer le poisson.",
        "Le piquer de gousses d'ail et de la moitié des olives.",
        "Peler et émincer les oignons, les faire fondre doucement dans une poêle avec l'huile d'olive pendant 5 min.",
        "Les retirer de la poêle et les réserver.",
        "Faire revenir le thon dans la même poêle, à feu vif, 3 min de chaque côté.",
        "Baisser le feu, ajouter les oignons, le jus de citron, les citrons confits et les olives restantes.",
        "Laisser cuire 20 min."
      ]
    }
  ]
}
